package main

import "fmt"

func safe() (err error) {
    defer func() {
        if r := recover(); r != nil {
            err = fmt.Errorf("восстановлено: %v", r)
        }
    }()
    panic("сбой")
}

func main() {
    fmt.Println(safe())
    fmt.Println("программа жива")
}
